def opening_balances(apps, schema_editor):
    """Existing earnings get their month. Money already requested or paid
    out before this system counts as released, so no balance changes."""
    from django.db.models import Sum
    from django.utils import timezone
    Earning = apps.get_model('wallet', 'AuthorEarning')
    Payout = apps.get_model('wallet', 'Payout')
    Release = apps.get_model('wallet', 'IncomeRelease')
    for e in Earning.objects.filter(period__isnull=True).only('pk', 'created_at'):
        Earning.objects.filter(pk=e.pk).update(period=timezone.localtime(e.created_at).date().replace(day=1))
    committed = ('pending', 'review', 'hold', 'approved', 'paid')
    for row in (Payout.objects.filter(status__in=committed).values('author')
                .annotate(t=Sum('amount_cents'))):
        if row['t']:
            Release.objects.create(author_id=row['author'], amount_cents=row['t'],
                                   note='Opening balance: requested or paid before Author Income Update')


